declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/ai.php';$u=current_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$q=$pdo->prepare("SELECT a.public_id FROM annotations a WHERE a.public_id=? AND a.visibility='public' AND a.status='published'");$q->execute([$id]);$a=$q->fetch();if(!$a){http_response_code(404);exit('Annotation not found.');}$done=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$reason=trim((string)($_POST['reason']??''));$description=trim((string)($_POST['description']??''));if($reason==='')$error='Choose a reason.';else{$reportPublic=ulid_like();$pdo->prepare("INSERT INTO moderation_reports(public_id,reported_by_user_id,object_type,object_public_id,reason,description) VALUES(?,?,'annotation',?,?,?)")->execute([$reportPublic,$u['id']??null,$id,$reason,$description?:null]);try{$model=ai_setting_model_id($pdo,'moderation');if($model)ai_queue_job($pdo,$u['id']??null,'moderation_report_triage',$model,'moderation_report',$reportPublic,[],2);}catch(Throwable $e){}$done=true;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report annotation · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="panel narrow"><h1>Report annotation</h1><?php if($done):?><div class="success">Report submitted for review.</div><p><a href="/annotation.php?id=<?=h($id)?>">Return to annotation</a></p><?php else:?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($id)?>"><label>Reason<select name="reason" required><option value="">Choose…</option><option value="spam">Spam</option><option value="harassment">Harassment</option><option value="impersonation">Impersonation</option><option value="misinformation_context">Misleading or manipulated context</option><option value="illegal_content">Illegal content concern</option><option value="other">Other</option></select></label><label>Details<textarea name="description" rows="6"></textarea></label><button>Submit report</button></form><p class="meta">Copyright, attribution, ownership, privacy, and fair-use concerns should use <a href="/file-a-claim.php?id=<?=h($id)?>">File a claim</a>.</p><?php endif?></main></body></html>
